const input = $('Webhook').first().json.body ?? $('Webhook').first().json;
const catalog = $input.all().flatMap((item) => item.json.data ?? item.json.models ?? []);
const tier = String(input.budget_tier ?? 'balanced').toLowerCase();
const preferred = {
  low: ['gpt-5-mini', 'gpt-5-nano', 'deepseek-v4-flash'],
  balanced: ['gpt-5.5', 'claude-sonnet-5.5', 'gemini-3.5-flash'],
  quality: ['claude-opus-4.8', 'gpt-5.5', 'gemini-3.5-flash']
}[tier] ?? ['gpt-5.5'];
const liveIds = new Set(catalog.map((model) => model.id ?? model.name).filter(Boolean));
const model = preferred.find((candidate) => liveIds.has(candidate)) ?? (input.model && liveIds.has(input.model) ? input.model : (catalog[0]?.id ?? 'gpt-5.5'));
return [{ json: { ...input, model, routing: { tier, preferred, catalog_count: catalog.length } } }];
